{"claims":[{"claim_text":"The Administration has strengthened dozens of environmental and safety standards to reduce smog, soot, carbon, methane, mercury, and other toxic pollutants in communities.", "claim_types":["factual_assertion"],"evidence_ids":[1]},{"claim_text":"After 30 years of inadequate protections, a ban on all cancer-causing asbestos, including from homes, cars, and water filtration sites, was implemented.", "claim_types":["factual_assertion"],"evidence_ids":[1]},{"claim_text":"The use of chlorpyrifos, a pesticide that can sicken farmworkers and children, was prohibited.", "claim_types":["factual_assertion"],"evidence_ids":[1]},{"claim_text":"America's first national drinking water standard was set to protect local water supplies from pollution with PFAS, toxic \"forever chemicals\" linked to cancer.", "claim_types":["factual_assertion"],"evidence_ids":[2]},{"claim_text":"Wastewater systems are being upgraded through the Bipartisan Infrastructure Law.", "claim_types":["factual_assertion"],"evidence_ids":[2]},{"claim_text":"Every toxic lead pipe in America is being replaced.", "claim_types":["policy_position"],"evidence_ids":[2]},{"claim_text":"The Bipartisan Infrastructure Law includes work to speed the cleanup of toxic Superfund and brownfield sites that have leached poisonous waste into nearby neighborhoods for decades.", "claim_types":["factual_assertion"],"evidence_ids":[3]},{"claim_text":"A \"polluter pays\" tax was restored through the Bipartisan Infrastructure Law, collecting revenue on chemicals sold in the United States and directing it to the Superfund Trust Fund to pay for cleanup.", "claim_types":["factual_assertion"],"evidence_ids":[3]},{"claim_text":"The \"polluter pays\" tax had lapsed 26 years before its restoration.", "claim_types":["factual_assertion"],"evidence_ids":[3]}],"unresolved_references":[]}
